void AdAccounts::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Get("/ad_accounts/{ad_account_id}/targeting_analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdtargetingAnalyticsGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdanalyticsGetRequest(req, res, auth);
    });
    svr.Post("/ad_accounts", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsPostRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsGetRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/reports/brand_category_sku", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdreportsbrandCategorySkuPostRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/mmm_reports", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdmmmReportsPostRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/reports", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdreportsPostRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/templates/{template_id}/reports", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdtemplatestemplateIdreportsPostRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/reports/brand_category_sku", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdreportsbrandCategorySkuGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/mmm_reports", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdmmmReportsGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/reports", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdreportsGetRequest(req, res, auth);
    });
    svr.Delete("/ad_accounts/{ad_account_id}/sandbox", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdsandboxDeleteRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/templates", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdtemplatesGetRequest(req, res, auth);
    });
}

